printf 'import json\nimport sys\nimport urllib.request\n\nport = open('\''port.txt'\'').read().strip()\n\n\ndef ask(messages):\n    body = json.dumps({'\''messages'\'': messages}).encode()\n    return json.load(urllib.request.urlopen('\''http://127.0.0.1:%%s/chat'\'' %% port, body, timeout=5))\n\n\ndef count_lines(path):\n    return str(len(open(path).read().splitlines()))\n\n\nmessages = [{'\''role'\'': '\''user'\'', '\''content'\'': sys.argv[1]}]\nfor step in range(5):\n    reply = ask(messages)\n    if reply['\''type'\''] == '\''text'\'':\n        print(reply['\''text'\''])\n        sys.exit(0)\n    messages.append({'\''role'\'': '\''assistant'\'', '\''tool_call'\'': reply})\n    try:\n        args = reply['\''arguments'\'']\n        if isinstance(args, str):\n            args = json.loads(args)\n        result = count_lines(args['\''path'\''])\n    except (ValueError, KeyError, TypeError, OSError) as err:\n        result = '\''error: %%s'\'' %% err\n    messages.append({'\''role'\'': '\''tool'\'', '\''id'\'': reply['\''id'\''], '\''content'\'': result})\nprint('\''gave up after 5 steps'\'')\nsys.exit(1)\n' > agent.py
